package org.efootballrevival.runtimeprobe;
import java.util.*;import java.util.function.*;import org.json.*;
public final class PlayerSearchIndex {
 private static final class Entry{final JSONObject row;final String name,id,type,key;final int position,overall,level,owned;Entry(JSONObject r,JSONArray positions,Function<String,String> translate){row=r;name=r.optString("name");id=r.optString("id");type=r.optString("card_type_label");position=r.optInt("position",-1);overall=r.optInt("overall");level=r.optInt("level_limit");owned=r.optInt("owned");key=EditorSearch.fold(name+" "+r.optString("name_en")+" "+id+" "+type+" "+translate.apply(type)+" "+(positions==null?"":positions.optString(position)));}}
 private final Entry[] entries;
 public PlayerSearchIndex(JSONArray rows,JSONArray positions,Function<String,String> translate,BooleanSupplier cancelled){ArrayList<Entry> list=new ArrayList<>(rows.length());for(int i=0;i<rows.length();i++){if((i&63)==0&&cancelled.getAsBoolean())throw new java.util.concurrent.CancellationException();JSONObject row=rows.optJSONObject(i);if(row!=null)list.add(new Entry(row,positions,translate));}entries=list.toArray(new Entry[0]);}
 public ArrayList<JSONObject> filter(String query,int position,String type,int sort,BooleanSupplier cancelled){String[] words=EditorSearch.tokens(query);ArrayList<Entry> selected=new ArrayList<>();for(int i=0;i<entries.length;i++){if((i&127)==0&&cancelled.getAsBoolean())throw new java.util.concurrent.CancellationException();Entry e=entries[i];if((position<0||position==e.position)&&(type.isEmpty()||type.equals(e.type))&&EditorSearch.textMatches(words,e.key))selected.add(e);}selected.sort((a,b)->{int c=sort==0?Integer.compare(b.overall,a.overall):sort==2?Integer.compare(b.level,a.level):sort==3?Integer.compare(a.owned,b.owned):0;if(c==0)c=a.name.compareTo(b.name);return c==0?a.id.compareTo(b.id):c;});if(cancelled.getAsBoolean())throw new java.util.concurrent.CancellationException();ArrayList<JSONObject> out=new ArrayList<>(selected.size());for(Entry e:selected)out.add(e.row);return out;}
 public int size(){return entries.length;}
}
